import { PurgeCSS } from "../src/index";

describe("Raw CSS optional filename", () => {
  it("Should return the `name` in the result's `file` property when provided for raw CSS option", async () => {
    return new PurgeCSS()
      .purge({
        content: [
          { raw: "<html><body><h1></h1></body></html>", extension: "html" },
        ],
        css: [
          { raw: "body{margin:0;}", name: "test.css" },
          { raw: "h1{margin:1;}" },
        ],
      })
      .then((results) => {
        expect(results.length).toBe(2);
        expect(
          results.some((result) => {
            return result.file && result.file.endsWith("test.css");
          }),
        ).toBe(true);
        results.forEach((result) => expect(typeof result.css).toBe("string"));
      });
  });
  it("Should NOT return the `name` in the result's `file` property when NOT provided for raw CSS option", async () => {
    return new PurgeCSS()
      .purge({
        content: [
          { raw: "<html><body><h1></h1></body></html>", extension: "html" },
        ],
        css: [{ raw: "body{margin:0;}" }],
      })
      .then((results) => {
        expect(results.length).toBe(1);
        expect(results[0].file).toBe(undefined);
        results.forEach((result) => expect(typeof result.css).toBe("string"));
      });
  });

  it("Should use the `name` as the path of the raw CSS in the source map", async () => {
    const [result] = await new PurgeCSS().purge({
      content: [{ raw: "<h1></h1>", extension: "html" }],
      css: [
        { raw: "h1 { margin: 0 }\n.unused { margin: 1px }", name: "app.css" },
      ],
      sourceMap: { inline: false },
    });
    expect(result.file).toBe("app.css");
    expect(result.css).toBe(
      "h1 { margin: 0 }\n/*# sourceMappingURL=app.css.map */",
    );
    const sourceMap = JSON.parse(result.sourceMap!);
    expect(sourceMap.sources).toEqual(["app.css"]);
    expect(sourceMap.file).toBe("app.css");
  });
  it("Should resolve a `name` with a directory like the path of a CSS file", async () => {
    const css = [{ raw: "h1 { margin: 0 }", name: "static/css/main.css" }];
    const content = [{ raw: "<h1></h1>", extension: "html" }];
    // relative to the directory of `to`, which defaults to the name
    const [result] = await new PurgeCSS().purge({
      content,
      css,
      sourceMap: { inline: false },
    });
    expect(result.file).toBe("static/css/main.css");
    const sourceMap = JSON.parse(result.sourceMap!);
    expect(sourceMap.sources).toEqual(["main.css"]);
    expect(sourceMap.file).toBe("main.css");

    const [resultTo] = await new PurgeCSS().purge({
      content,
      css,
      sourceMap: { inline: false, to: "main.min.css" },
    });
    const sourceMapTo = JSON.parse(resultTo.sourceMap!);
    expect(sourceMapTo.sources).toEqual(["static/css/main.css"]);
    expect(sourceMapTo.file).toBe("main.min.css");
  });
  it("Should keep the source map name of raw CSS without `name`", async () => {
    const [result] = await new PurgeCSS().purge({
      content: [{ raw: "<h1></h1>", extension: "html" }],
      css: [{ raw: "h1 { margin: 0 }" }],
      sourceMap: { inline: false },
    });
    expect(result.file).toBe(undefined);
    const sourceMap = JSON.parse(result.sourceMap!);
    // a name generated by postcss, e.g. `<input css 1>`
    expect(sourceMap.sources).toHaveLength(1);
    expect(decodeURIComponent(sourceMap.sources[0])).toMatch(/^<input css /);
  });
});
